import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"What is a View","description":"Understand views in ApptiveGrid — seven view types on the same data.","frontmatter":{"title":"What is a View","description":"Understand views in ApptiveGrid — seven view types on the same data."},"headers":[],"relativePath":"en/ansichten/was-ist-eine-ansicht.md","filePath":"en/ansichten/was-ist-eine-ansicht.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/was-ist-eine-ansicht.md"};function s(o,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="what-is-a-view" tabindex="-1">What is a View <a class="header-anchor" href="#what-is-a-view" aria-label="Permalink to &quot;What is a View&quot;">​</a></h1><p>A <strong>View</strong> is a particular way of displaying a Grid. It determines which entries are visible, in what order they appear, how they&#39;re grouped, and which columns show up.</p><p><strong>A view doesn&#39;t change the data.</strong> It&#39;s a lens on the same Grid.</p><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>This is the most common point of confusion in ApptiveGrid. Get the distinction clear early on:</p><table tabindex="0"><thead><tr><th></th><th>Grid</th><th>View</th></tr></thead><tbody><tr><td>Contains</td><td>the data</td><td>only display rules</td></tr><tr><td>On deletion</td><td>data is gone</td><td>data is retained</td></tr><tr><td>Count</td><td>one per dataset</td><td>any number per Grid</td></tr></tbody></table><p>A Grid &quot;Tasks&quot; can simultaneously have:</p><ul><li>a table with all tasks,</li><li>a filtered table with only open tasks,</li><li>a Kanban board by status,</li><li>a calendar by due date.</li></ul><p>Four views, one dataset. If someone changes a task in the Kanban board, the change is immediately visible in every other view.</p><div class="danger custom-block"><p class="custom-block-title">Deleting a view affects forms</p><p>Forms and shared links are attached to a view. When deleting, ApptiveGrid warns that your created forms will no longer work after deletion.</p><p>Before deleting, check whether forms or shared links are attached to this view. The dataset is retained, but an externally distributed form link becomes invalid.</p></div><h2 id="the-seven-view-types" tabindex="-1">The seven view types <a class="header-anchor" href="#the-seven-view-types" aria-label="Permalink to &quot;The seven view types&quot;">​</a></h2><h3 id="grid-view" tabindex="-1">Grid view <a class="header-anchor" href="#grid-view" aria-label="Permalink to &quot;Grid view&quot;">​</a></h3><p>The classic table: rows are entries, columns are fields. The default and the starting point for everything else.</p><p>Suited for: data maintenance, bulk editing, a complete overview.</p><h3 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h3><p>Cards in columns that can be moved via drag and drop. The columns come from a field of type <strong>Single Select</strong> — usually a status field.</p><p>Which details appear on a card is configured per view.</p><p>Suited for: workflows with clear stages such as applications, tickets, sales opportunities.</p><p>→ <a href="/en/ansichten/kanban">Kanban</a></p><h3 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h3><p>Entries on a calendar sheet, positioned via a date field.</p><p>Suited for: appointments, deadlines, bookings.</p><p>→ <a href="/en/ansichten/kalender">Calendar</a></p><h3 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h3><p>Entries as markers on a map, positioned via a field of type <strong>Address</strong> or <strong>Geolocation</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Requirement for addresses</p><p>For an address to appear as a map marker, coordinates have to be determined for it. This geocoding depends on your plan. For fields of type <em>Geolocation</em> with directly entered coordinates, this restriction doesn&#39;t apply.</p></div><p>→ <a href="/en/ansichten/karte">Map</a></p><h3 id="gallery" tabindex="-1">Gallery <a class="header-anchor" href="#gallery" aria-label="Permalink to &quot;Gallery&quot;">​</a></h3><p>Entries as cards with images. The card layout is configurable.</p><p>Suited for: product catalogs, people directories, anything image-heavy.</p><p>→ <a href="/en/ansichten/galerie">Gallery</a></p><h3 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h3><p>A compact, stacked display — more space-efficient than the table and especially readable on narrow screens.</p><p>→ <a href="/en/ansichten/liste">List</a></p><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><p>Entries on a timeline, in the <em>Day</em>, <em>Week</em>, <em>Month</em>, and <em>Year</em> grids. Suited for project planning and booking schedules.</p><div class="warning custom-block"><p class="custom-block-title">Two requirements</p><ol><li><strong>A field of type <em>Link multiple records</em>.</strong> Without it, ApptiveGrid reports: <em>To see a Timeline, your Grid needs a column of type multiple link.</em> This link field determines the rows of the timeline.</li><li><strong>Date fields in the linked Grid</strong> for start and end. If they&#39;re missing, ApptiveGrid reports: <em>The referenced Grid has no date or date-time fields.</em></li></ol><p>The Timeline is thus the only view configured across two Grids.</p><p>It&#39;s also plan-dependent.</p></div><p>→ <a href="/en/ansichten/timeline">Timeline</a></p><h2 id="create-a-view" tabindex="-1">Create a view <a class="header-anchor" href="#create-a-view" aria-label="Permalink to &quot;Create a view&quot;">​</a></h2><ol><li>In the sidebar, under the Grid, select the <strong>Views</strong> area.</li><li>Click <strong>Create view</strong>.</li><li>Choose the view type.</li><li>Give it a name.</li></ol><div class="tip custom-block"><p class="custom-block-title">Duplicating saves work</p><p>Via <em>More</em> (⋮) → <strong>Duplicate</strong>, you create a copy with all filters, sorts, and column settings. Faster than building a similar view from scratch.</p></div><h2 id="what-belongs-to-the-view-and-what-belongs-to-the-grid" tabindex="-1">What belongs to the view and what belongs to the Grid <a class="header-anchor" href="#what-belongs-to-the-view-and-what-belongs-to-the-grid" aria-label="Permalink to &quot;What belongs to the view and what belongs to the Grid&quot;">​</a></h2><p>This distinction saves a lot of confusion within a team:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Applies to</th></tr></thead><tbody><tr><td>Filter</td><td><strong>this view only</strong></td></tr><tr><td>Sort</td><td><strong>this view only</strong></td></tr><tr><td>Grouping</td><td><strong>this view only</strong></td></tr><tr><td>Hidden columns</td><td><strong>this view only</strong></td></tr><tr><td>Column order</td><td><strong>this view only</strong></td></tr><tr><td>Locked columns</td><td><strong>this view only</strong></td></tr><tr><td>Empty state text</td><td><strong>this view only</strong></td></tr><tr><td>Field name</td><td><strong>the entire Grid</strong></td></tr><tr><td>Column type</td><td><strong>the entire Grid</strong></td></tr><tr><td>Select options</td><td><strong>the entire Grid</strong></td></tr><tr><td>Entries and values</td><td><strong>the entire Grid</strong></td></tr></tbody></table><p>In short: anything to do with <em>display</em> belongs to the view. Anything to do with <em>structure and content</em> belongs to the Grid.</p><p>So renaming a column changes it everywhere. Hiding a column only affects your view.</p><h2 id="sharing-a-view" tabindex="-1">Sharing a view <a class="header-anchor" href="#sharing-a-view" aria-label="Permalink to &quot;Sharing a view&quot;">​</a></h2><p>Every view can be shared as a private link. Recipients only see the data visible in this view — filters and hidden columns act as a visual barrier too.</p><div class="warning custom-block"><p class="custom-block-title">Filters aren&#39;t full access protection</p><p>For truly sensitive data, don&#39;t rely solely on hiding it in a shared view. Also apply an <a href="/en/zusammenarbeit/zugriff-beschraenken">access restriction</a> to the link.</p></div><p>→ <a href="/en/ansichten/ansicht-teilen">Sharing a view</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li><li><a href="/en/ansichten/spalten-verwalten">Manage columns</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li></ul>',52)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
